import json,sqlite3
with open('json/schools.json') as f: data=json.load(f)
schools={r['CDSCode']:r for r in data['records'] if r.get('District')=='Fresno Unified'}
conn=sqlite3.connect('db/satscores.db')
cur=conn.cursor()
cur.execute('SELECT cds, AvgScrRead FROM satscores WHERE AvgScrRead IS NOT NULL')
scores={row[0]:row[1] for row in cur.fetchall()}
conn.close()
avgs={cds: (school['Phone'], scores[cds]) for cds,school in schools.items() if cds in scores}
if avgs:
  lowest=min(avgs, key=lambda x: avgs[x][1])
  print(f'{lowest[0]}|{avgs[lowest][0]}|{avgs[lowest][1]}')
else:
